mapper.select:
select
con.Con_Name as conName, con.Con_Code as conCode, c1.C_Name as baCompanyName, c2.C_Name as baWageCName, c1.C_Abbreviation as baCompanyAbbName, c2.C_Abbreviation as baWageCAbbName, mn.* from Bank_Account_Change mn
left join Con_Contract con on con.Con_Id=mn.Con_Id left join Bank_Account ba1 on ba1.Ba_Id=mn.Ba_Id_N left join Bank_Account ba2 on ba2.Ba_Id=mn.Ba_Id_Wage_N left join SYS_Company c1 on ba1.Ba_C_Id=c1.C_Id left join SYS_Company c2 on ba2.Ba_C_Id=c2.C_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Bac_Create_Time DESC
